const fallback=langs.id;let activeLang=localStorage.getItem('jtm-language')||'id';
document.querySelector('#site-header').innerHTML=`<header class="site-header"><a class="brand" href="index.html"><img src="assets/logo.png" alt="JasaTiketMurah.com"></a><button class="menu-toggle" aria-label="Menu">☰</button><nav class="main-nav"><a href="index.html" data-i18n="home">Beranda</a><a href="inspiration.html" data-i18n="inspiration">Inspirasi</a><a href="about.html" data-i18n="about">Tentang kami</a><a href="contact.html" data-i18n="contact">Hubungi kami</a></nav><div class="header-right"><select id="language" class="language-select" aria-label="Language"><option value="id">🇮🇩 Indonesia</option><option value="en">🇬🇧 English</option><option value="th">🇹🇭 ไทย</option><option value="zh">🇨🇳 中文</option><option value="ja">🇯🇵 日本語</option><option value="ko">🇰🇷 한국어</option></select><button class="account-button" data-i18n="login">Masuk</button></div></header>`;
document.querySelector('#site-footer').innerHTML=`<footer><div class="wrap footer-grid"><div><img class="footer-logo" src="assets/logo.png" alt="JasaTiketMurah.com"><p>Flight · Hotel · Tour · Visa · Transfer</p></div><div><h3 data-i18n="footerExplore">Jelajahi</h3><a href="index.html#booking" data-i18n="flight">Pesawat</a><a href="index.html#booking" data-i18n="hotel">Hotel</a><a href="index.html#booking" data-i18n="tour">Tur</a><a href="index.html#booking" data-i18n="visa">Visa</a></div><div><h3 data-i18n="footerCompany">Perusahaan</h3><a href="about.html" data-i18n="about">Tentang kami</a><a href="contact.html" data-i18n="contact">Hubungi kami</a><a href="#">Syarat & ketentuan</a><a href="#">Kebijakan privasi</a></div><div><h3 data-i18n="footerHelp">Bantuan</h3><a href="mailto:cs@jasatiketmurah.com">cs@jasatiketmurah.com</a><a href="contact.html">Pusat bantuan</a></div></div><div class="wrap copyright">Copyright © 2011-<span id="year"></span> JasaTiketMurah.com by PT Shiro Xpress International. <span data-i18n="rights">All rights reserved.</span></div></footer>`;
function translate(){const dict={...fallback,...langs[activeLang]};document.documentElement.lang=activeLang;document.querySelectorAll('[data-i18n]').forEach(el=>{const text=dict[el.dataset.i18n];if(text)el.textContent=text});document.querySelector('#language').value=activeLang;document.title=document.title.replace(/^.*? \| /,'')+' | JasaTiketMurah';}
translate();document.querySelector('#year').textContent=new Date().getFullYear();document.querySelector('#language').addEventListener('change',e=>{activeLang=e.target.value;localStorage.setItem('jtm-language',activeLang);translate()});document.querySelector('.menu-toggle').addEventListener('click',()=>document.querySelector('.main-nav').classList.toggle('open'));
const dateField=document.querySelector('#travel-date');if(dateField){dateField.min=new Date().toISOString().split('T')[0];dateField.value=new Date(Date.now()+12096e5).toISOString().split('T')[0];const presets={flight:['Jakarta (CGK)','Pilih kota tujuan'],hotel:['','Contoh: Ubud, Bali'],tour:['','Contoh: Tokyo city tour'],visa:['Indonesia','Contoh: Jepang']};document.querySelectorAll('.service-tab').forEach(tab=>tab.addEventListener('click',()=>{document.querySelectorAll('.service-tab').forEach(t=>t.classList.remove('active'));tab.classList.add('active');const p=presets[tab.dataset.service];document.querySelector('#origin').value=p[0];document.querySelector('#destination').value='';document.querySelector('#destination').placeholder=p[1]}));document.querySelector('.swap').addEventListener('click',()=>{const a=document.querySelector('#origin'),b=document.querySelector('#destination');[a.value,b.value]=[b.value,a.value]});document.querySelector('#search-form').addEventListener('submit',e=>{e.preventDefault();document.querySelector('#search-feedback').textContent='Pencarian Anda siap. Harga live akan tersedia setelah integrasi API.'})}
let answer;function captcha(){const a=Math.floor(Math.random()*90)+10,b=Math.floor(Math.random()*(a+1));answer=a-b;const label=document.querySelector('#captcha-label');if(label)label.firstChild.textContent=`${langs[activeLang].verification||fallback.verification}: ${a} − ${b} = `}captcha();document.querySelector('#contact-form')?.addEventListener('submit',e=>{e.preventDefault();const f=document.querySelector('#contact-feedback');if(Number(document.querySelector('#captcha').value)!==answer){f.textContent='Jawaban verifikasi belum tepat.';captcha();return}f.textContent='Terima kasih. Pesan Anda siap dikirim ke tim kami.';e.currentTarget.reset();captcha()});

const routeLinks=['/','/inspiration/','/about/','/contact/'];document.querySelectorAll('#site-header .main-nav a').forEach((link,index)=>link.href=routeLinks[index]);document.querySelectorAll('img[src="assets/logo.png"]').forEach(image=>image.src='/assets/logo.png');const legalLinks=document.querySelectorAll('#site-footer a[href="#"]');if(legalLinks[0])legalLinks[0].href='/terms/';if(legalLinks[1])legalLinks[1].href='/privacy/';
const aboutCopy={id:'<p>Jasa Tiket Murah hadir untuk membantu pelanggan menyusun perjalanan dengan lebih tenang. Kami memahami bahwa setiap perjalanan memiliki kebutuhan yang berbeda: perjalanan bisnis yang terjadwal, liburan keluarga, kunjungan singkat, hingga perjalanan internasional yang memerlukan persiapan visa.</p><p>Layanan kami mencakup pencarian tiket pesawat, hotel, tur dan aktivitas, pengurusan visa, serta transfer. Kami berfokus pada informasi yang jelas, pilihan yang relevan, dan bantuan yang mudah dijangkau saat pelanggan memerlukannya.</p><p>Di balik setiap pesanan, Jasa Tiket Murah ingin menjadi partner yang dapat diandalkan—dari tahap perencanaan hingga perjalanan selesai.</p>',en:'<p>Jasa Tiket Murah helps travellers plan with greater confidence. Every trip has different needs: a scheduled business journey, a family holiday, a short visit, or an international itinerary that requires visa preparation.</p><p>Our services cover flights, hotels, tours and activities, visa assistance, and transfers. We focus on clear information, relevant options, and accessible support when travellers need it.</p><p>Behind every booking, Jasa Tiket Murah aims to be a dependable partner from planning through the end of your journey.</p>',th:'<p>Jasa Tiket Murah ช่วยให้ผู้เดินทางวางแผนได้อย่างมั่นใจยิ่งขึ้น เราให้บริการเที่ยวบิน โรงแรม ทัวร์ วีซ่า และรถรับส่ง พร้อมข้อมูลที่ชัดเจนและการสนับสนุนที่เข้าถึงได้</p>',zh:'<p>Jasa Tiket Murah 协助旅客更安心地规划行程。我们提供机票、酒店、旅游活动、签证协助和接送服务，并提供清晰的信息与支持。</p>',ja:'<p>Jasa Tiket Murah は、お客様が安心して旅を計画できるよう支援します。航空券、ホテル、ツアー、ビザ、送迎をわかりやすい情報とともにご案内します。</p>',ko:'<p>Jasa Tiket Murah는 고객이 더 안심하고 여행을 계획하도록 돕습니다. 항공권, 호텔, 투어, 비자, 픽업 서비스를 명확한 정보와 함께 제공합니다.</p>'};document.querySelector('#about-copy')?.insertAdjacentHTML('beforeend',aboutCopy[activeLang]||aboutCopy.id);
['about','contact'].forEach(name=>document.querySelectorAll(`a[href="${name}.html"]`).forEach(link=>link.href=`/${name}/`));Object.values(langs).forEach(dict=>['heroEyebrow','inspirationEyebrow','aboutEyebrow','contactEyebrow'].forEach(key=>delete dict[key]));langs.id.aboutSub='Sejak 2011, Jasa Tiket Murah membantu pelanggan menyusun perjalanan domestik dan internasional dengan layanan yang jelas dan personal.';langs.en.aboutSub='Since 2011, Jasa Tiket Murah has helped travellers arrange domestic and international journeys with clear, personal service.';translate();
document.querySelector('#language').addEventListener('change',()=>{const target=document.querySelector('#about-copy');if(target)target.innerHTML=aboutCopy[activeLang]||aboutCopy.id});

// Flight booking flow: trip type, traveller allocation (maximum seven), and date rules.
const bookingForm=document.querySelector('#search-form');
if(bookingForm){
  const tabs=document.createElement('div');tabs.className='trip-types';tabs.innerHTML='<label><input type="radio" name="trip-type" value="one-way" checked> Sekali jalan</label><label><input type="radio" name="trip-type" value="round-trip"> Pulang-pergi</label><label><input type="radio" name="trip-type" value="multi-city"> Multi-kota</label>';
  document.querySelector('.search-card').insertBefore(tabs,bookingForm);
  const travellerLabel=bookingForm.querySelectorAll('label')[3];
  travellerLabel.innerHTML='<small>Penumpang</small><button type="button" class="traveller-trigger" aria-expanded="false">1 dewasa</button><div class="traveller-popover" hidden><div class="traveller-row"><span><b>Dewasa</b><small>12 tahun ke atas</small></span><div class="counter"><button type="button" data-counter="adults" data-step="-1">−</button><output data-count="adults">1</output><button type="button" data-counter="adults" data-step="1">+</button></div></div><div class="traveller-row"><span><b>Anak</b><small>2–11 tahun</small></span><div class="counter"><button type="button" data-counter="children" data-step="-1">−</button><output data-count="children">0</output><button type="button" data-counter="children" data-step="1">+</button></div></div><div class="traveller-row"><span><b>Bayi</b><small>Di bawah 2 tahun</small></span><div class="counter"><button type="button" data-counter="infants" data-step="-1">−</button><output data-count="infants">0</output><button type="button" data-counter="infants" data-step="1">+</button></div></div><p class="traveller-note">Maksimal 7 penumpang per pemesanan.</p><button type="button" class="traveller-done">Selesai</button></div>';
  const state={adults:1,children:0,infants:0};const trigger=travellerLabel.querySelector('.traveller-trigger');const popover=travellerLabel.querySelector('.traveller-popover');
  const refreshTravellers=()=>{Object.entries(state).forEach(([key,value])=>travellerLabel.querySelector(`[data-count="${key}"]`).textContent=value);const pieces=[];if(state.adults)pieces.push(`${state.adults} dewasa`);if(state.children)pieces.push(`${state.children} anak`);if(state.infants)pieces.push(`${state.infants} bayi`);trigger.textContent=pieces.join(', ');travellerLabel.querySelectorAll('.counter button[data-step="1"]').forEach(button=>button.disabled=state.adults+state.children+state.infants>=7);travellerLabel.querySelector('[data-counter="adults"][data-step="-1"]').disabled=state.adults<=1;['children','infants'].forEach(key=>travellerLabel.querySelector(`[data-counter="${key}"][data-step="-1"]`).disabled=state[key]===0)};
  trigger.addEventListener('click',()=>{popover.hidden=!popover.hidden;trigger.setAttribute('aria-expanded',String(!popover.hidden))});travellerLabel.querySelector('.traveller-done').addEventListener('click',()=>{popover.hidden=true;trigger.setAttribute('aria-expanded','false')});travellerLabel.querySelectorAll('[data-counter]').forEach(button=>button.addEventListener('click',()=>{const key=button.dataset.counter;const next=state[key]+Number(button.dataset.step);if(next>=0&&state.adults+state.children+state.infants+Number(button.dataset.step)<=7&&(key!=='adults'||next>=1)){state[key]=next;refreshTravellers()}}));refreshTravellers();
  const departure=document.querySelector('#travel-date');const returnField=document.createElement('label');returnField.className='return-date';returnField.hidden=true;returnField.innerHTML='<small>Tanggal pulang</small><input id="return-date" type="date">';departure.parentElement.after(returnField);const returnDate=returnField.querySelector('input');
  const syncReturn=()=>{returnDate.min=departure.value||new Date().toISOString().slice(0,10);if(returnDate.value&&returnDate.value<returnDate.min)returnDate.value=returnDate.min};departure.addEventListener('change',syncReturn);syncReturn();
  tabs.addEventListener('change',event=>{if(event.target.name!=='trip-type')return;if(event.target.value==='multi-city'){window.location.href='/multi-city/';return}returnField.hidden=event.target.value!=='round-trip';returnDate.required=event.target.value==='round-trip';if(!returnDate.value)returnDate.value=returnDate.min});
  bookingForm.addEventListener('submit',event=>{if(returnField.hidden===false&&returnDate.value<departure.value){event.preventDefault();document.querySelector('#search-feedback').textContent='Tanggal pulang tidak boleh lebih awal dari tanggal berangkat.'}});
}

document.head.insertAdjacentHTML('beforeend','<style>.trip-types{display:flex;gap:18px;padding:16px 0 4px;font-size:.88rem;font-weight:600;color:#334155}.trip-types label{display:flex;align-items:center;gap:6px;cursor:pointer}.trip-types input{accent-color:#1e3a8a}.traveller-trigger{height:48px;text-align:left;border:1px solid #cbd5e1;border-radius:5px;background:#fff;padding:10px;color:#0d1b2a;font:500 .91rem DM Sans;cursor:pointer}.traveller-popover{position:absolute;z-index:8;top:76px;right:0;width:320px;padding:14px;background:#fff;border:1px solid #cbd5e1;border-radius:8px;box-shadow:0 16px 35px rgba(13,27,42,.18)}.search-form label{position:relative}.traveller-row{display:flex;justify-content:space-between;align-items:center;padding:10px 0;border-bottom:1px solid #e2e8f0}.traveller-row span{display:grid}.traveller-row small{font-weight:400;color:#64748b}.counter{display:flex;align-items:center;gap:11px}.counter button{width:28px;height:28px;border:1px solid #cbd5e1;background:#fff;border-radius:50%;font-size:18px;color:#1e3a8a;cursor:pointer}.counter button:disabled{opacity:.35;cursor:not-allowed}.counter output{min-width:14px;text-align:center}.traveller-note{font-size:.76rem;color:#64748b;margin:11px 0}.traveller-done{width:100%;border:0;background:#1e3a8a;color:#fff;border-radius:4px;padding:9px;font-weight:700;cursor:pointer}@media(max-width:560px){.trip-types{gap:12px;overflow:auto;white-space:nowrap}.traveller-popover{position:fixed;inset:auto 16px 16px;width:auto}.return-date{display:block!important}}</style>');
